-- Vira colorscheme for Neovim, built from the VS Code Vira Theme's own data.
--
-- Each installed variant is lua/vira/variants/<variant>.json: the extension's
-- theme JSON, generated by tools/vira-nvim.py in the dotfiles repository.
-- Regenerate or add variants with that tool instead of editing the JSON.

local M = {}

M.default_variant = "graphene"

M.accents = {
    ["vira"] = "#E9A581",
    ["white"] = "#FFFFFF",
    ["tomato"] = "#F85044",
    ["orange"] = "#FF7042",
    ["yellow"] = "#FFCF3D",
    ["acid-lime"] = "#C6FF00",
    ["lime"] = "#39EA5F",
    ["teal"] = "#80CBC4",
    ["bright-teal"] = "#64FFDA",
    ["cyan"] = "#57D7FF",
    ["blue"] = "#5393FF",
    ["indigo"] = "#758AFF",
    ["purple"] = "#B54DFF",
    ["pink"] = "#FF669E",
}

local variant_file = "lua/vira/variants/%s.json"

local decoded = {}
local built = {}

local function variant_path(key)
    if not key:match("^[%w-]+$") then
        return nil
    end
    return vim.api.nvim_get_runtime_file(variant_file:format(key), false)[1]
end

local function installed_variants()
    local names, seen = {}, {}
    for _, path in ipairs(vim.api.nvim_get_runtime_file(variant_file:format("*"), true)) do
        local name = vim.fn.fnamemodify(path, ":t:r")
        if not seen[name] then
            seen[name] = true
            table.insert(names, name)
        end
    end
    table.sort(names)
    return names
end

-- "graphene-high-contrast" -> "Vira Graphene High Contrast"
local function label_for(key)
    local words = key:gsub("%-", " "):gsub("(%a)(%w*)", function(first, rest)
        return first:upper() .. rest
    end)
    return "Vira " .. words
end

local function normalize_variant(name)
    local key = tostring(name or ""):lower():gsub("_", "-"):gsub("%s+", "-"):gsub("^vira%-", "")
    if variant_path(key) then
        return key
    end
    error(("unknown Vira variant %q; run :ViraTheme without arguments to choose one"):format(tostring(name)))
end

local function decode(name)
    local key = normalize_variant(name)
    if not decoded[key] then
        local file = assert(io.open(variant_path(key), "rb"))
        local text = file:read("*a")
        file:close()
        decoded[key] = vim.json.decode(text)
    end
    return decoded[key], key
end

local function replace_table(target, source)
    for key in pairs(target) do
        target[key] = nil
    end
    for key, value in pairs(source) do
        target[key] = value
    end
end

local function rgb(value)
    if type(value) ~= "string" then
        return nil
    end
    local red, green, blue = value:match("^#(%x%x)(%x%x)(%x%x)$")
    if not red then
        return nil
    end
    return tonumber(red, 16), tonumber(green, 16), tonumber(blue, 16)
end

local function opaque(value)
    if type(value) ~= "string" then
        return nil
    end
    if #value == 7 and value:match("^#%x%x%x%x%x%x$") then
        return value
    end
    if #value == 9 and value:match("^#%x%x%x%x%x%x%x%x$") then
        return value:sub(1, 7)
    end
    return nil
end

local function blend(value, backdrop)
    if type(value) ~= "string" then
        return nil
    end
    if value:match("^#%x%x%x%x%x%x$") then
        return value
    end

    local red, green, blue, alpha = value:match("^#(%x%x)(%x%x)(%x%x)(%x%x)$")
    if not red then
        return nil
    end
    local back_red, back_green, back_blue = rgb(backdrop)
    if not back_red then
        return "#" .. red .. green .. blue
    end

    local amount = tonumber(alpha, 16) / 255
    local function channel(foreground, background)
        return math.floor(tonumber(foreground, 16) * amount + background * (1 - amount) + 0.5)
    end

    return ("#%02X%02X%02X"):format(channel(red, back_red), channel(green, back_green), channel(blue, back_blue))
end

local function ui(theme, name, fallback, backdrop)
    return blend(theme.colors[name], backdrop or theme.colors["editor.background"]) or fallback
end

local function token(theme, name, fallback)
    for _, rule in ipairs(theme.tokenColors) do
        if rule.name == name and rule.settings and rule.settings.foreground then
            return blend(rule.settings.foreground, theme.colors["editor.background"]) or fallback
        end
    end
    return fallback
end

local function token_style(theme, name)
    for _, rule in ipairs(theme.tokenColors) do
        if rule.name == name and rule.settings then
            local font_style = rule.settings.fontStyle or ""
            return {
                bold = font_style:find("bold", 1, true) ~= nil,
                italic = font_style:find("italic", 1, true) ~= nil,
                underline = font_style:find("underline", 1, true) ~= nil,
            }
        end
    end
    return {}
end

local function semantic_color(theme, name, fallback)
    local value = theme.semanticTokenColors[name]
    if type(value) == "table" then
        value = value.foreground
    end
    return blend(value, theme.colors["editor.background"]) or fallback
end

local function build(name)
    local theme, key = decode(name)
    if built[key] then
        return built[key]
    end

    local background = ui(theme, "editor.background", "#000000")
    local foreground = ui(theme, "editor.foreground", "#D9D9D9", background)
    local surface = ui(theme, "editorWidget.background", background, background)
    if surface:lower() == background:lower() then
        surface = ui(theme, "input.background", background, background)
    end
    local selection = ui(theme, "editor.selectionBackground", surface, background)
    local visual_selection = opaque(theme.colors["editor.selectionBackground"]) or selection
    local comment = token(theme, "Comment", foreground)
    local muted = ui(theme, "editorLineNumber.activeForeground", comment, background)
    local accent = ui(theme, "button.background", M.accents.teal, background)

    local semantic = {}
    for semantic_name in pairs(theme.semanticTokenColors) do
        semantic[semantic_name] = semantic_color(theme, semantic_name, foreground)
    end

    local result = {
        key = key,
        label = label_for(key),
        high_contrast = key:find("%-high%-contrast$") ~= nil,
        source_file = theme._source and theme._source.file,
        source = theme,
        palette = {
            base00 = background,
            base01 = surface,
            base02 = selection,
            base03 = comment,
            base04 = muted,
            base05 = foreground,
            base06 = semantic.selfParameter or token(theme, "CSS properties", foreground),
            base07 = ui(theme, "terminal.ansiBrightWhite", "#FFFFFF", background),
            base08 = token(theme, "Modules", "#F07178"),
            base09 = token(theme, "Number", "#F78C6C"),
            base0A = token(theme, "Type", "#FFCB6B"),
            base0B = token(theme, "String", "#C3E88D"),
            base0C = token(theme, "Punctuation", "#89DDFF"),
            base0D = token(theme, "Function call", "#82AAFF"),
            base0E = token(theme, "Storage", "#C792EA"),
            base0F = token(theme, "Boolean", "#FF9CAC"),
        },
        colors = {
            accent = accent,
            background = background,
            foreground = foreground,
            surface = surface,
            selection = selection,
            visual_selection = visual_selection,
            muted = muted,
            comment = comment,
            black = ui(theme, "terminal.ansiBlack", "#000000", background),
            cursor = ui(theme, "editorCursor.foreground", accent, background),
            line_number = ui(theme, "editorLineNumber.foreground", comment, background),
            line_number_active = muted,
            search = ui(theme, "editor.findMatchBackground", selection, background),
            search_highlight = ui(theme, "editor.findMatchHighlightBackground", selection, background),
            error = ui(theme, "editorError.foreground", token(theme, "Modules", "#F07178"), background),
            warning = ui(theme, "editorWarning.foreground", token(theme, "Type", "#FFCB6B"), background),
            info = ui(theme, "editorInfo.foreground", token(theme, "Function call", "#82AAFF"), background),
            hint = ui(theme, "editorHint.foreground", token(theme, "Punctuation", "#89DDFF"), background),
            git_add = ui(
                theme,
                "gitDecoration.untrackedResourceForeground",
                token(theme, "String", "#C3E88D"),
                background
            ),
            git_change = ui(
                theme,
                "gitDecoration.modifiedResourceForeground",
                token(theme, "Function call", "#82AAFF"),
                background
            ),
            git_delete = ui(
                theme,
                "gitDecoration.deletedResourceForeground",
                token(theme, "Modules", "#F07178"),
                background
            ),
            diff_add = ui(theme, "diffEditor.insertedLineBackground", selection, background),
            diff_delete = ui(theme, "diffEditor.removedLineBackground", selection, background),
        },
        tokens = {
            string = token(theme, "String", foreground),
            punctuation = token(theme, "Punctuation", foreground),
            escape = token(theme, "String Escape", foreground),
            boolean = token(theme, "Boolean", foreground),
            number = token(theme, "Number", foreground),
            variable = token(theme, "Variable", foreground),
            keyword = token(theme, "Keyword", foreground),
            other_keyword = token(theme, "Other Keyword", foreground),
            function_call = token(theme, "Function call", foreground),
            storage = token(theme, "Storage", foreground),
            module = token(theme, "Modules", foreground),
            type = token(theme, "Type", foreground),
            class = token(theme, "Class", foreground),
            comment = comment,
            preprocessor = token(theme, "C# preprocessor", comment),
            markdown_heading = token(theme, "Markdown heading", foreground),
            markdown_link = token(theme, "Markdown link text", foreground),
            markdown_code = token(theme, "Markdown code block", foreground),
        },
        semantic = semantic,
        styles = {
            comment = token_style(theme, "Comment"),
            keyword = token_style(theme, "Keyword Control"),
        },
    }

    built[key] = result
    return result
end

M.palette = {}
M.colors = {}
M.tokens = {}
M.semantic = {}
M.styles = {}
M.vscode_colors = {}
M.token_colors = {}
M.semantic_token_colors = {}

function M.names()
    return installed_variants()
end

function M.label(name)
    return label_for(normalize_variant(name))
end

function M.get_source(name)
    local theme = decode(name)
    return vim.deepcopy(theme)
end

function M.stats(name)
    local theme, key = decode(name)
    return {
        key = key,
        label = label_for(key),
        source = theme._source,
        ui_colors = vim.tbl_count(theme.colors),
        token_rules = #theme.tokenColors,
        semantic_tokens = vim.tbl_count(theme.semanticTokenColors),
    }
end

function M.select(name)
    local theme = build(name)
    M.current_variant = theme.key
    M.current_label = theme.label
    vim.g.vira_variant = theme.key
    replace_table(M.palette, theme.palette)
    replace_table(M.colors, theme.colors)
    replace_table(M.tokens, theme.tokens)
    replace_table(M.semantic, theme.semantic)
    replace_table(M.styles, theme.styles)
    replace_table(M.vscode_colors, theme.source.colors)
    replace_table(M.token_colors, theme.source.tokenColors)
    replace_table(M.semantic_token_colors, theme.source.semanticTokenColors)
    return theme.key
end

local transparent_groups = {
    "Normal",
    "NormalNC",
    "EndOfBuffer",
    "SignColumn",
    "FoldColumn",
    "LineNr",
    "LineNrAbove",
    "LineNrBelow",
    "CursorLine",
    "CursorLineNr",
    "CursorLineSign",
    "CursorLineFold",
    "StatusColumn",
    "StatusColumnNC",
    "DiagnosticSignError",
    "DiagnosticSignWarn",
    "DiagnosticSignInfo",
    "DiagnosticSignHint",
    "DiagnosticSignOk",
    "StatusLine",
    "StatusLineNC",
    "TabLine",
    "TabLineFill",
    "TabLineSel",
    "WinBar",
    "WinBarNC",
    "WinSeparator",
    "VertSplit",
    "NeoTreeNormal",
    "NeoTreeNormalNC",
    "NeoTreeEndOfBuffer",
    "NeoTreeWinSeparator",
    "TroubleNormal",
    "TroubleNormalNC",
    "SnacksNormal",
    "SnacksDashboardNormal",
    "MiniFilesNormal",
    "Terminal",
    "BufferLineFill",
    "BufferLineBackground",
    "BufferLineBufferVisible",
    "BufferLineBufferSelected",
}

local function set(group, highlight)
    vim.api.nvim_set_hl(0, group, highlight)
end

local function clear_background(group)
    local ok, highlight = pcall(vim.api.nvim_get_hl, 0, { name = group, link = false })
    if not ok then
        highlight = {}
    end
    highlight.bg = nil
    highlight.ctermbg = nil
    vim.api.nvim_set_hl(0, group, highlight)
end

local function apply_semantic_tokens()
    for semantic_name, color in pairs(M.semantic) do
        local parts = vim.split(semantic_name, ".", { plain = true })
        local token_type = table.remove(parts, 1)
        if #parts == 0 then
            set("@lsp.type." .. token_type, { fg = color })
        else
            for _, modifier in ipairs(parts) do
                set("@lsp.typemod." .. token_type .. "." .. modifier, { fg = color })
            end
        end
    end
end

function M.apply()
    local p = M.palette
    local c = M.colors
    local t = M.tokens

    set("Normal", { fg = c.foreground, bg = "NONE" })
    set("NormalNC", { fg = c.foreground, bg = "NONE" })
    set("Cursor", { fg = c.background, bg = c.cursor })
    set("CursorLine", { bg = "NONE" })
    set("CursorLineNr", { fg = c.accent, bg = "NONE", bold = true })
    set("LineNr", { fg = c.line_number, bg = "NONE" })
    set("WinSeparator", { fg = p.base02, bg = "NONE" })
    set("Visual", { bg = c.visual_selection })
    set("VisualNOS", { bg = c.visual_selection })
    set("Search", { fg = c.foreground, bg = c.search, bold = true })
    set("IncSearch", { fg = c.background, bg = c.accent, bold = true })
    set("CurSearch", { link = "IncSearch" })
    set("MatchParen", { fg = c.accent, bg = "NONE", bold = true })
    set("Directory", { fg = c.accent })
    set("Title", { fg = c.accent, bold = true })

    set("NormalFloat", { fg = c.foreground, bg = c.surface })
    set("FloatBorder", { fg = c.accent, bg = c.surface })
    set("FloatTitle", { fg = c.accent, bg = c.surface, bold = true })
    set("Pmenu", { fg = c.foreground, bg = c.surface })
    set("PmenuSel", { fg = p.base07, bg = p.base02, bold = true })
    set("PmenuMatch", { fg = c.accent, bg = c.surface, bold = true })
    set("PmenuMatchSel", { fg = c.accent, bg = p.base02, bold = true })
    set("PmenuSbar", { bg = c.surface })
    set("PmenuThumb", { bg = p.base04 })

    set("StatusLine", { fg = c.foreground, bg = "NONE" })
    set("StatusLineNC", { fg = p.base04, bg = "NONE" })
    set("TabLine", { fg = p.base04, bg = "NONE" })
    set("TabLineFill", { bg = "NONE" })
    set("TabLineSel", { fg = p.base07, bg = "NONE", bold = true, italic = true })

    set("Comment", vim.tbl_extend("force", { fg = t.comment }, M.styles.comment))
    set("String", { fg = t.string })
    set("Character", { fg = t.string })
    set("Number", { fg = t.number })
    set("Float", { fg = t.number })
    set("Boolean", { fg = t.boolean })
    set("Identifier", { fg = t.variable })
    set("Function", { fg = t.function_call })
    set("Statement", { fg = t.keyword })
    set("Keyword", { fg = t.keyword })
    set("Conditional", { fg = t.keyword })
    set("Repeat", { fg = t.keyword })
    set("Exception", { fg = t.keyword })
    set("Operator", { fg = t.punctuation })
    set("Delimiter", { fg = t.punctuation })
    set("PreProc", { fg = t.preprocessor })
    set("Include", { fg = t.module, italic = true })
    set("StorageClass", { fg = t.storage })
    set("Type", { fg = t.type })
    set("Structure", { fg = t.class })
    set("Typedef", { fg = t.type })
    set("Special", { fg = t.escape })

    set("@comment", { link = "Comment" })
    set("@string", { fg = t.string })
    set("@string.escape", { fg = t.escape })
    set("@boolean", { fg = t.boolean })
    set("@number", { fg = t.number })
    set("@variable", { fg = M.semantic.variable or t.variable })
    set("@variable.parameter", { fg = M.semantic["parameter.declaration"] or t.variable, italic = true })
    set("@variable.builtin", { fg = M.semantic["variable.defaultLibrary"] or t.variable, italic = true })
    set("@keyword", { fg = t.keyword })
    set("@keyword.import", { fg = t.module, italic = true })
    set("@operator", { fg = t.punctuation })
    set("@punctuation", { fg = t.punctuation })
    set("@function", { fg = M.semantic["function"] or t.function_call })
    set("@function.call", { fg = M.semantic["function"] or t.function_call })
    set("@function.method", { fg = M.semantic["function"] or t.function_call })
    set("@function.method.call", { fg = M.semantic["function"] or t.function_call })
    set("@type", { fg = M.semantic.type or t.type })
    set("@type.builtin", { fg = M.semantic["class.typeHint.builtin"] or t.type })
    set("@module", { fg = M.semantic.module or t.module, italic = true })
    set("@constant", { fg = M.semantic["variable.constant"] or t.variable })
    set("@constant.builtin", { fg = t.boolean, italic = true })
    set("@markup.heading", { fg = t.markdown_heading, bold = true })
    set("@markup.link", { fg = t.markdown_link, underline = true })
    set("@markup.raw", { fg = t.markdown_code })
    apply_semantic_tokens()

    set("DiagnosticError", { fg = c.error })
    set("DiagnosticWarn", { fg = c.warning })
    set("DiagnosticInfo", { fg = c.info })
    set("DiagnosticHint", { fg = c.hint })
    set("DiagnosticUnderlineError", { undercurl = true, sp = c.error })
    set("DiagnosticUnderlineWarn", { undercurl = true, sp = c.warning })
    set("DiagnosticUnderlineInfo", { undercurl = true, sp = c.info })
    set("DiagnosticUnderlineHint", { undercurl = true, sp = c.hint })
    set("LspInlayHint", { fg = p.base04, bg = "NONE", italic = true })

    set("DiffAdd", { fg = c.git_add, bg = c.diff_add })
    set("DiffChange", { fg = c.git_change, bg = c.diff_add })
    set("DiffDelete", { fg = c.git_delete, bg = c.diff_delete })
    set("GitSignsAdd", { fg = c.git_add, bg = "NONE" })
    set("GitSignsChange", { fg = c.git_change, bg = "NONE" })
    set("GitSignsDelete", { fg = c.git_delete, bg = "NONE" })
    set("NeoTreeGitAdded", { fg = c.git_add })
    set("NeoTreeGitModified", { fg = c.git_change })
    set("NeoTreeGitDeleted", { fg = c.git_delete })

    set("TelescopeNormal", { fg = c.foreground, bg = c.surface })
    set("TelescopeBorder", { fg = c.accent, bg = c.surface })
    set("TelescopePromptNormal", { fg = c.foreground, bg = c.surface })
    set("TelescopePromptBorder", { fg = c.accent, bg = c.surface })
    set("TelescopePromptTitle", { fg = c.background, bg = c.accent, bold = true })
    set("TelescopeSelection", { fg = p.base07, bg = p.base02, bold = true })
    set("TelescopeMatching", { fg = c.accent, bold = true })
    set("WhichKey", { fg = c.accent })
    set("WhichKeyGroup", { fg = p.base0D })
    set("WhichKeyDesc", { fg = c.foreground })

    set("BufferLineFill", { fg = p.base03, bg = "NONE" })
    set("BufferLineBackground", { fg = p.base04, bg = "NONE" })
    set("BufferLineBufferVisible", { fg = p.base05, bg = "NONE" })
    set("BufferLineBufferSelected", { fg = p.base07, bg = "NONE", bold = true, italic = true })
    set("BufferLineIndicatorSelected", { fg = c.accent, bg = "NONE" })
    set("BufferLineSeparator", { fg = p.base02, bg = "NONE" })
    set("BufferLineSeparatorVisible", { fg = p.base02, bg = "NONE" })
    set("BufferLineSeparatorSelected", { fg = p.base02, bg = "NONE" })

    for _, group in ipairs(transparent_groups) do
        clear_background(group)
    end
end

function M.lualine_theme()
    local p = M.palette
    local function mode(color)
        return {
            a = { fg = p.base00, bg = color, gui = "bold" },
            b = { fg = p.base05, bg = "NONE" },
            c = { fg = p.base04, bg = "NONE" },
        }
    end
    return {
        normal = mode(p.base0D),
        insert = mode(p.base0B),
        visual = mode(p.base0E),
        replace = mode(p.base08),
        command = mode(p.base0A),
        terminal = mode(p.base0C),
        inactive = {
            a = { fg = p.base04, bg = "NONE" },
            b = { fg = p.base04, bg = "NONE" },
            c = { fg = p.base04, bg = "NONE" },
        },
    }
end

local function refresh_lualine()
    if not package.loaded.lualine then
        return
    end
    local lualine = require("lualine")
    local config = lualine.get_config()
    config.options.theme = M.lualine_theme()
    lualine.setup(config)
end

function M.load(name, opts)
    opts = opts or {}
    local key = M.select(name)
    vim.cmd("highlight clear")
    vim.o.background = "dark"
    require("mini.base16").setup({
        palette = M.palette,
        use_cterm = false,
        plugins = { default = true },
    })
    vim.g.colors_name = opts.colors_name or ("vira-" .. key)
    M.apply()
    refresh_lualine()

    if not opts.skip_autocmd and vim.v.vim_did_enter == 1 then
        vim.api.nvim_exec_autocmds("ColorScheme", { pattern = vim.g.colors_name })
    end
    return key
end

local initial_variant = vim.g.vira_variant or M.default_variant
if not pcall(M.select, initial_variant) then
    M.select(M.default_variant)
end

if vim.fn.exists(":ViraTheme") == 0 then
    vim.api.nvim_create_user_command("ViraTheme", function(opts)
        local function activate(choice)
            if not choice then
                return
            end
            local ok, result = pcall(M.load, choice)
            if ok then
                vim.notify(("Vira theme: %s"):format(M.current_label), vim.log.levels.INFO)
            else
                vim.notify(result, vim.log.levels.ERROR)
            end
        end

        if opts.args == "" then
            vim.ui.select(installed_variants(), {
                prompt = "Vira theme",
                format_item = function(item)
                    return label_for(item)
                end,
            }, activate)
        else
            activate(opts.args)
        end
    end, {
        nargs = "?",
        complete = function(arg_lead)
            return vim.tbl_filter(function(item)
                return item:find(arg_lead, 1, true) == 1
            end, installed_variants())
        end,
        desc = "Select an installed Vira theme variant",
    })
end

return M
